package httpx_test

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/egdaemon/eg/internal/httpx"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestContextBufferPool(t *testing.T) {
	t.Run("handler receives a buffer from the pool via context", func(t *testing.T) {
		pool := httpx.NewBufferPool(1024)
		var gotCap int
		middleware := httpx.ContextBufferPool(pool)
		handler := middleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			buf := httpx.GetBuffer(r)
			require.NotNil(t, buf)
			gotCap = buf.Cap()
			buf.WriteString("hello")
		}))

		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		handler.ServeHTTP(rec, req)

		require.Equal(t, http.StatusOK, rec.Code)
		require.GreaterOrEqual(t, gotCap, 1024)
	})

	t.Run("multiple buffer acquisitions are tracked and released", func(t *testing.T) {
		pool := httpx.NewBufferPool(512)
		var caps []int
		middleware := httpx.ContextBufferPool(pool)
		handler := middleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			b1 := httpx.GetBuffer(r)
			b2 := httpx.GetBuffer(r)
			require.NotNil(t, b1)
			require.NotNil(t, b2)
			caps = append(caps, b1.Cap(), b2.Cap())
			httpx.ReleaseBuffer(r, b1)
		}))

		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		handler.ServeHTTP(rec, req)

		require.Equal(t, http.StatusOK, rec.Code)
		require.Len(t, caps, 2)
		require.GreaterOrEqual(t, caps[0], 512)
		require.GreaterOrEqual(t, caps[1], 512)
	})

	t.Run("without middleware get buffer returns a fresh empty buffer", func(t *testing.T) {
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		buf := httpx.GetBuffer(req)
		require.NotNil(t, buf)
		require.Equal(t, 0, buf.Len())
	})

	t.Run("middleware does not alter the response body", func(t *testing.T) {
		pool := httpx.NewBufferPool(1024)
		middleware := httpx.ContextBufferPool(pool)
		handler := middleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("response-body"))
		}))

		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		handler.ServeHTTP(rec, req)

		require.Equal(t, http.StatusOK, rec.Code)
		require.Equal(t, "response-body", rec.Body.String())
	})

	t.Run("convenience 1024 wrapper produces a working handler", func(t *testing.T) {
		var gotCap int
		middleware := httpx.ContextBufferPool1024()
		handler := middleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			buf := httpx.GetBuffer(r)
			require.NotNil(t, buf)
			gotCap = buf.Cap()
		}))

		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		handler.ServeHTTP(rec, req)

		require.Equal(t, http.StatusOK, rec.Code)
		require.GreaterOrEqual(t, gotCap, 1024)
	})

	t.Run("convenience 512 wrapper produces a working handler", func(t *testing.T) {
		var gotCap int
		middleware := httpx.ContextBufferPool512()
		handler := middleware(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			buf := httpx.GetBuffer(r)
			require.NotNil(t, buf)
			gotCap = buf.Cap()
		}))

		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		handler.ServeHTTP(rec, req)

		require.Equal(t, http.StatusOK, rec.Code)
		require.GreaterOrEqual(t, gotCap, 512)
	})
}
